109	<script>
110	  import { pluralizeUk } from "../lib/i18n/plural";
111	
112	  const numberFormatter = new Intl.NumberFormat("uk-UA");
113	  const formatCount = (value) =>
114	    typeof value === "number" ? numberFormatter.format(value) : "-";
115	  const formatBytesUk = (value) =>
116	    typeof value === "number" ? `${(value / (1024 * 1024)).toFixed(1)} МБ` : "-";
117	  const formatBytesEn = (value) =>
118	    typeof value === "number" ? `${(value / (1024 * 1024)).toFixed(1)} MB` : "-";
119	  const escapeHtml = (value) =>
120	    String(value ?? "").replace(
121	      /[&<>"']/g,
122	      (c) =>
123	        ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c] ?? c,
124	    );
125	
126	  function setRuntimeText(root, key, value) {
127	    const node = root.querySelector(`[data-runtime-value="${key}"]`);
128	    if (node) node.textContent = value;
129	  }
130	
131	  function setRuntimeDetailHtml(root, key, uk, en) {
132	    const node = root.querySelector(`[data-runtime-detail="${key}"]`);
133	    if (!node) return;
134	    node.innerHTML = `<span data-loc="uk">${escapeHtml(uk)}</span><span data-loc="en">${escapeHtml(en)}</span>`;
135	    node.classList.add("lu-i18n-block");
136	  }
137	
138	  function setRuntimeStatusHtml(root, uk, en) {
139	    const statusNode = root.querySelector("[data-runtime-status]");
140	    if (!statusNode) return;
141	    statusNode.innerHTML = `<span data-loc="uk">${escapeHtml(uk)}</span><span data-loc="en">${escapeHtml(en)}</span>`;
142	    statusNode.classList.add("lu-i18n-block");
143	  }
144	
145	  function renderRuntimeStatus(root, status) {
146	    setRuntimeText(root, "publicAtlas", formatCount(status.entryModel.total_reviewed_entries));
147	    
148	    const aliasCount = status.entryModel.alias_records ?? 0;
149	    const aliasLabel = pluralizeUk(aliasCount, ["пошукова словоформа", "пошукові словоформи", "пошукових словоформ"]);
150	    
151	    const shardCount = status.publicAtlas.searchShards ?? 0;
152	    const shardLabel = pluralizeUk(shardCount, ["сегмент пошуку", "сегменти пошуку", "сегментів пошуку"]);
153	
154	    setRuntimeDetailHtml(
155	      root,
156	      "publicAtlas",
157	      `${formatCount(aliasCount)} ${aliasLabel} · ${formatCount(shardCount)} ${shardLabel}`,
158	      `${formatCount(aliasCount)} search wordforms · ${formatCount(shardCount)} search shards`,
159	    );
160	
161	    setRuntimeText(root, "manifest", formatCount(status.manifest.records));
162	    
163	    const publicCount = status.manifest.publicLexemeRecords ?? 0;
164	    const publicLabel = pluralizeUk(publicCount, ["публічний запис", "публічні записи", "публічних записів"]);
165	    
166	    const grammarCount = status.manifest.grammarTermRecords ?? 0;
167	    const grammarLabel = pluralizeUk(grammarCount, ["внутрішній", "внутрішні", "внутрішніх"]);
168	
169	    setRuntimeDetailHtml(
170	      root,
171	      "manifest",
172	      status.manifest.hydrated
173	        ? `${formatCount(publicCount)} ${publicLabel} · ${formatCount(grammarCount)} ${grammarLabel}`
174	        : `${formatBytesUk(status.manifest.jsonBytes)} закріплено`,
175	      status.manifest.hydrated
176	        ? `${formatCount(publicCount)} public records · ${formatCount(grammarCount)} internal`
177	        : `${formatBytesEn(status.manifest.jsonBytes)} pinned`,
178	    );
179	
180	    setRuntimeText(root, "api", "4");
181	    setRuntimeDetailHtml(root, "api", status.endpoints.contract, status.endpoints.contract);
182	
183	    setRuntimeText(root, "daily", formatCount(status.daily.poolEntries));
184	    setRuntimeDetailHtml(root, "daily", "Навчальна добірка", "Learning selection");
185	
186	    setRuntimeText(root, "practice", formatCount(status.practice.totalLexemes));
187	    setRuntimeDetailHtml(
188	      root,
189	      "practice",
190	      status.practice.deckVersions.length
191	        ? status.practice.deckVersions.join(", ")
192	        : "Без версії",
193	      status.practice.deckVersions.length
194	        ? status.practice.deckVersions.join(", ")
195	        : "No version",
196	    );
197	
198	    setRuntimeText(root, "cloze", formatCount(status.cloze.totalItems));
199	    setRuntimeDetailHtml(
200	      root,
201	      "cloze",
202	      `${formatCount(status.cloze.sourceRows)} джерел · ${formatCount(
203	        status.cloze.reviewedSourceRows,
204	      )} дозволено`,
205	      `${formatCount(status.cloze.sourceRows)} sources · ${formatCount(
206	        status.cloze.reviewedSourceRows,
207	      )} allowed`,
208	    );
209	
210	    setRuntimeText(root, "sourceInventory", formatCount(status.sourceInventory.atlasRows));
211	    setRuntimeDetailHtml(
212	      root,
213	      "sourceInventory",
214	      `${formatCount(status.sourceInventory.dailyAdmitted)} / ${formatCount(
215	        status.sourceInventory.practiceAdmitted,
216	      )} / ${formatCount(status.sourceInventory.clozeAdmitted)}`,
217	      `${formatCount(status.sourceInventory.dailyAdmitted)} / ${formatCount(
218	        status.sourceInventory.practiceAdmitted,
219	      )} / ${formatCount(status.sourceInventory.clozeAdmitted)}`,
220	    );
221	
222	    if (status.status === "ok") {
223	      setRuntimeStatusHtml(
224	        root,
225	        "Дані узгоджені: пошук, перегляд, Слова дня і практика синхронізовані.",
226	        "Data aligned: search, browse, Words of the Day, and practice are in sync.",
227	      );
228	    } else {
229	      setRuntimeStatusHtml(
230	        root,
231	        "Дані потребують перевірки: одна з поверхонь Атласу не збігається.",
232	        "Data needs review: one Atlas surface is out of sync.",
233	      );
234	    }
235	    root.dataset.runtimeLoaded = "true";
236	  }
237	
238	  for (const root of document.querySelectorAll("[data-atlas-runtime]")) {
239	    const endpoint = root.dataset.statusUrl || "/api/lexicon/status.json";
240	    fetch(endpoint)
241	      .then((response) => {
242	        if (!response.ok) throw new Error(`Atlas status failed: ${response.status}`);
243	        return response.json();
244	      })
245	      .then((status) => renderRuntimeStatus(root, status))
246	      .catch(() => {
247	        setRuntimeStatusHtml(
248	          root,
249	          "Стан Атласу зараз недоступний.",
250	          "Atlas status is unavailable right now.",
251	        );
252	        root.dataset.runtimeLoaded = "false";
253	      });
254	  }
255	</script>
