args.content:
#!/usr/bin/env node
// WCAG 2.x contrast ratio for hex color pairs. Usage: node contrast.mjs '#fg' '#bg' [opacity]
function lum(hex) {
  const c = hex.replace('#', '');
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(c.slice(i, i + 2), 16) / 255);
  const lin = (v) => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}
function blend(fg, bg, a) {
  const p = (h, i) => parseInt(h.replace('#', '').slice(i, i + 2), 16);
  const mix = [0, 2, 4].map((i) => Math.round(a * p(fg, i) + (1 - a) * p(bg, i)));
  return '#' + mix.map((v) => v.toString(16).padStart(2, '0')).join('');
}
const [fg, bg, opacity] = process.argv.slice(2);
const effFg = opacity ? blend(fg, bg, Number(opacity)) : fg;
const [l1, l2] = [lum(effFg), lum(bg)].sort((a, b) => b - a);
const ratio = (l1 + 0.05) / (l2 + 0.05);
console.log(
  `${fg}${opacity ? ` @${opacity} → ${effFg}` : ''} on ${bg}: ${ratio.toFixed(2)}:1 ${ratio >= 4.5 ? 'PASS' : ratio >= 3 ? 'FAIL(AA normal; large-text only)' : 'FAIL'}`,
);

