import { chromium } from '@playwright/test';

const base = 'http://127.0.0.1:4487';
const browser = await chromium.launch();
for (const theme of ['light', 'dark']) {
  const page = await browser.newPage();
  await page.addInitScript((t) => {
    window.localStorage.setItem('lu-theme', t);
    document.documentElement.setAttribute('data-theme', t);
  }, theme);
  await page.goto(`${base}/words-of-the-day/practice/`);
  await page.waitForSelector('#lexicon-practice-mount .lexicon-practice', { timeout: 15000 });
  await page.evaluate((t) => document.documentElement.setAttribute('data-theme', t), theme);
  await page.waitForTimeout(800);
  const deck = page.locator('.practice-daily-deck');
  await deck.screenshot({ path: `/tmp/6814-deck-${theme}.png` });
  // open the counters <details> for a shot of the status pills
  await page.locator('.daily-deck-details summary').click();
  await page.waitForTimeout(300);
  await deck.screenshot({ path: `/tmp/6814-deck-counters-${theme}.png` });

  await page.goto(`${base}/lexicon/`);
  await page.evaluate((t) => document.documentElement.setAttribute('data-theme', t), theme);
  await page.waitForTimeout(1200);
  const grid = page.locator('.atlas-runtime-panel');
  await grid.screenshot({ path: `/tmp/6815-runtime-${theme}.png` });
  await page.close();
}
await browser.close();
console.log('shots done');
